    question: "Why do we use Nested Classes?",
    answer: "There are following reasons for using nested classes: 1 . Logical Grouping: We can logically group classes in one place. If one class is useful to only one other class, then we put smaller class within the larger class and keep them in one file. This kind of nesting \"helper classes\" in a top- level class makes the package more streamlined. 2 . Encapsulation: Nested classes increase encapsulation. Let say there are two top-level classes, Foo and Bar. Bar needs access to private members of Foo. We can hide class Bar within class Foo.",
