    question: "How can you determine if your program has a deadlock?",
    answer: "If we suspect that our application is stuck due to a Deadlock, then we just take a thread dump by using the command specific to environment in which your application is running. Eg. In Linux you can use command kill -3. In case of deadlock, you will see in thread dump the current status and stack trace of threads in the JVM, and one or more of them will be stuck with message deadlock. Also you can do this programmatically by using the ThreadMXBean class that ships with the JDK.",
