    question: "What is the main difference between git clone and git remote?",
    answer: "The main difference between git clone and git remote is that git clone is used to create a new local repository whereas git remote is used in an existing repository. git remote adds a new reference to existing remote repository for tracking further changes. git clone creates a new local repository by copying another repository from a URL.",
