    question: "What does it mean that String is immutable in Java?",
    answer: "Immutable means unchangeable \u2014 once a String object is created, its value cannot be modified. Methods like concat() return a NEW String rather than changing the original. This is why `s.concat(\" Tendulkar\")` doesn't change s unless you reassign it.",
    code: "String s = \"Sachin\";\ns.concat(\" Tendulkar\");\nSystem.out.println(s); // Sachin  (unchanged)",
