    question: "How many objects are created by: String s1=\"X\"; String s2=\"X\"; String s3=\"X\"; ?",
    answer: "Only one object. All three literals are identical, so the JVM reuses the single pooled String \"X\" for s1, s2, and s3 (strings are immutable, so sharing is safe).",
