    question: "What are the differences between StringBuffer and StringBuilder?",
    answer: "StringBuffer is synchronized (thread-safe) but slower; two threads cannot call its methods simultaneously. StringBuilder is non-synchronized (not thread-safe) but faster and more efficient. Use StringBuilder for single-threaded string building, StringBuffer when thread safety is required.",
