    category: "oop",
    question: "What are the types of inner (non-static nested) classes in Java?",
    answer: "Three types: Member inner class (defined inside a class but outside any method), Anonymous inner class (an unnamed class created to implement an interface or extend a class, named by the compiler), and Local inner class (defined inside a method).",
