    question: "Your team needs to process 1 million events per minute. Which technology would you choose, and why?",
    answer: "First, do the math: 1,000,000 events/min \u2248 16,700 events/sec. That is high but very achievable \u2014 the trick is picking a system built for buffered, horizontally scalable, asynchronous ingestion instead of hammering a database or a synchronous REST endpoint. My default choice is a distributed log / streaming platform \u2014 Apache Kafka \u2014 as the ingestion backbone, with a stream processor (Kafka Streams, Apache Flink, or Spark Structured Streaming) on top. Why Kafka: (1) A partitioned, append-only commit log gives huge sequential-write throughput \u2014 Kafka comfortably handles millions of events/sec, so 16.7K/sec has plenty of headroom. (2) Partitions are the unit of parallelism: pick a good partition key and add partitions + consumers in a consumer group to scale horizontally and keep per-key ordering. (3) It decouples producers from consumers \u2014 producers never block on slow consumers, and the log absorbs bursts (natural back-pressure/buffering). (4) Replication gives durability and fault tolerance; retention lets you replay/reprocess events. (5) It integrates with the whole streaming ecosystem (Flink, Spark, ksqlDB, connectors). Managed equivalents if you do not want to run it: AWS Kinesis / MSK, Google Pub/Sub, or Azure Event Hubs. Apache Pulsar is a strong alternative when you need multi-tenancy or tiered storage. What I would NOT reach for: a traditional RabbitMQ/JMS broker (great for complex routing and per-message workflows, but not optimized for this raw throughput and replay), or writing straight to a relational DB per event (the DB becomes the bottleneck \u2014 instead batch-consume from Kafka and bulk-write). Key design points I would mention: choose the partition key for parallelism + ordering, batch and compress producer sends, size partitions to your target consumer parallelism, aim for idempotent or exactly-once processing, and monitor consumer lag. In short: Kafka (or a managed log like Kinesis/Pub/Sub) for durable, scalable, replayable ingestion, plus Flink/Kafka-Streams for real-time processing \u2014 because the problem is really about buffering and horizontal scale, not just raw speed.",
