    question: "Two senior engineers reviewed the same system. Dev A added Kafka between services; Dev B merged three synchronous API calls into one. Same traffic, same hardware — API latency dropped 80%. Whose design would you approve?",
    answer: "For the stated goal — an 80% drop in API latency — I would approve Dev B's design, but the trick is understanding WHY, because the two changes solve completely different problems. Dev B merged three synchronous calls into one composite/aggregator (BFF) API. The latency win comes from cutting network round-trips: three sequential client→service hops become one, and the aggregator can fan out to User/Pricing/Inventory internally (ideally in parallel). Fewer hops on the critical request path = dramatically lower latency. That is exactly what produced the 80%. Dev A added Kafka between services. Kafka is asynchronous, event-driven messaging — it improves decoupling, resilience, and scalability for fire-and-forget work (notifications, analytics, audit), and it smooths bursts. But it does NOT reduce synchronous request latency; if anything it adds a hop and operational complexity. You cannot 'speed up' a blocking read path by publishing events to Kafka — the client still has to wait for the data. So the classic trap here is reaching for Kafka to fix latency: Kafka is about throughput, decoupling, and async workflows, not request latency. If the problem is a read that fans out to three services, the right tool is an aggregator/BFF that merges and parallelizes the calls. The mature answer: it is not strictly either/or. Approve Dev B for the latency metric, and keep Dev A's Kafka exactly where it belongs — for the downstream async events (notifications, analytics, audit in Option A) that should never sit on the critical path. Caveats I would raise for Dev B before approving: parallelize the internal calls (not sequential), add timeouts, retries, and a circuit breaker, handle partial failures gracefully (return what you have), and watch that the aggregator does not become a single point of failure or get too tightly coupled to every service. In short: approve B because it targets the actual bottleneck (network hops on the sync path); Kafka (A) is a great tool aimed at a different problem.",
