export function searchJavaQuestions(query) {
  const q = query.trim().toLowerCase();
  if (!q) return JAVA_INTERVIEW_QUESTIONS;
  return JAVA_INTERVIEW_QUESTIONS.filter(
    (item) =>
      item.question.toLowerCase().includes(q) ||
      item.answer.toLowerCase().includes(q),
  );
}
